function consolidatedFixture(array $pairs,array $names=[],array $payments=[]):array
{
 $rows=[];$seq=0;foreach($pairs as $set){++$seq;$waivers=[];foreach($set as $p)$waivers[]=(string)$p['record'];$rows[]=['Group ID'=>'BMA-W-'.str_pad((string)$seq,4,'0',STR_PAD_LEFT),'Student name'=>$names[$seq-1]??'John Smith','Student name variants'=>'','Student birthdate(s)'=>'','Waiver count'=>(string)count($waivers),'Waiver IDs'=>implode(' | ',$waivers),'Contact email(s)'=>'','Primary phone(s)'=>'','Address(es)'=>'','Address line 1'=>'','Address line 2'=>'','City'=>'','State'=>'','Postal code'=>'','Waiver signer(s)'=>'','Relationship(s) to student'=>'','Stripe association status'=>'No Stripe association found','Stripe customer ID(s)'=>implode(' | ',array_column($set,'external'))];}
 $duplicates=[];foreach($rows as $r)if((int)$r['Waiver count']>1)$duplicates[]=['Group ID'=>$r['Group ID'],'Student'=>$r['Student name'],'Waivers consolidated'=>$r['Waiver count'],'Waiver IDs'=>$r['Waiver IDs']];return ['groups'=>$rows,'payments'=>$payments,'duplicates'=>$duplicates,'hashes'=>['synthetic'=>hash('sha256',json_encode([$rows,$payments]))]];
}
