 [$code]=$http('/admin/reconcile-consolidated.php');bulkCheck($code===303,'unauthenticated consolidated preview redirects to login');$q("UPDATE app_users SET role='viewer' WHERE id=?",[$users['admin']]);[$code]=$http('/admin/reconcile-consolidated.php',$cookie);bulkCheck($code===403,'viewer cannot access private consolidated preview');$q("UPDATE app_users SET role='admin' WHERE id=?",[$users['admin']]);[$code]=$http('/admin/reconcile-consolidated.php',$cookie,['apply'=>'1']);bulkCheck($code===405,'web reconciliation endpoint rejects write requests and has no apply action');
